 derived={'schemaVersion':'q025-derived-revalidation-receipt/1','jobId':d.name,'status':'complete','origin':'deterministic_revalidation','nativeTurnStartedHere':False,'model':receipt['model'],'effort':receipt['effort'],'sourceOnly':True,'sandbox':'read-only','toolUseAttempted':False,'threadId':receipt.get('threadId'),'turnId':receipt.get('turnId'),'independence':'Same original source-only screen; no new model call or independent challenge.','originalNativeStatus':'failed','originalError':receipt['error'],'originalJobPath':str(d.relative_to(E)),'originalReceiptSha256':sha(d/'receipt.json'),'inputPins':{'packetSha256':sha(target/'packet.actual.json'),'originalPacketSha256':sha(d/'packet.actual.json')},'replySha256':sha(target/'reply.raw.txt'),'normalizedReplySha256':sha(target/'reply.json'),'normalizationReceiptSha256':sha(target/'normalization.json'),'scientificAdmission':False,'identityAdmission':False,'navigationAdmission':False};dump(target/'receipt.json',derived)
